 for tool in ["/usr/bin/perf","/home/ubuntu/src/zk-tools/zopro/xtask/target/release/xtask"]{add(tool,&mut pins);}let mut c=read("/tmp/zopro-prefix-pool/perf-plan.json");let mut cases=c["cases"].as_array().unwrap().clone();assert_eq!(cases.len(),9);for c in &mut cases{c["rounds"]=json!(31);c["profile_rounds"]=json!(251);for key in ["image","request"]{add(c[key].as_str().unwrap(),&mut pins);}}let mut physical=cases.iter().find(|c|c["shape"]=="1x2").unwrap().clone();physical["name"]=json!("1x2-w16");physical["workers"]=json!(16);physical["rounds"]=json!(151);physical["cpu_affinity"]=json!("0-15");cases.push(physical);for(p,h)in c["pins"].as_object().unwrap(){if p.contains("/registry/")||p.starts_with("/tmp/zopro-keys/")||p.starts_with("/tmp/zopro-gnark-verify/"){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}}
